/* Generated by Trae Work */
(function () {
  const canvas = document.getElementById("fx-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");

  const DPR = Math.min(2, window.devicePixelRatio || 1);
  let w = 0;
  let h = 0;

  function resize() {
    w = Math.floor(window.innerWidth * DPR);
    h = Math.floor(window.innerHeight * DPR);
    canvas.width = w;
    canvas.height = h;
    canvas.style.width = "100%";
    canvas.style.height = "100%";
  }
  window.addEventListener("resize", resize);
  resize();

  // Tiny particle field + drifting gradient blobs
  const particleCount = Math.floor(Math.min(160, Math.max(70, window.innerWidth / 10)));
  const particles = Array.from({ length: particleCount }, () => ({
    x: Math.random() * w,
    y: Math.random() * h,
    r: (Math.random() * 2.2 + 0.6) * DPR,
    vx: (Math.random() - 0.5) * 0.22 * DPR,
    vy: (Math.random() - 0.5) * 0.22 * DPR,
    a: 0.15 + Math.random() * 0.35
  }));

  const blobs = [
    { x: 0.2, y: 0.25, r: 0.45, hue: "rgba(47,123,255,0.18)", dx: 0.00008, dy: 0.00006 },
    { x: 0.8, y: 0.78, r: 0.42, hue: "rgba(255,58,58,0.16)", dx: -0.00007, dy: -0.00005 },
    { x: 0.55, y: 0.35, r: 0.34, hue: "rgba(120,80,255,0.10)", dx: 0.00006, dy: -0.00008 }
  ];

  function step(t) {
    ctx.clearRect(0, 0, w, h);

    // Blobs
    for (const b of blobs) {
      b.x = (b.x + b.dx * (t || 16)) % 1;
      b.y = (b.y + b.dy * (t || 16)) % 1;
      const cx = b.x * w;
      const cy = b.y * h;
      const r = b.r * Math.max(w, h);
      const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
      g.addColorStop(0, b.hue);
      g.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.fill();
    }

    // Particles
    for (const p of particles) {
      p.x += p.vx;
      p.y += p.vy;
      if (p.x < -20) p.x = w + 20;
      if (p.x > w + 20) p.x = -20;
      if (p.y < -20) p.y = h + 20;
      if (p.y > h + 20) p.y = -20;

      ctx.fillStyle = `rgba(234,241,255,${p.a})`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // Subtle scanline overlay
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = "rgba(0,0,0,1)";
    for (let y = 0; y < h; y += 6 * DPR) {
      ctx.fillRect(0, y, w, 1 * DPR);
    }
    ctx.globalAlpha = 1;

    requestAnimationFrame(step);
  }

  requestAnimationFrame(step);
})();

